    # ### Backfill: Ensure all existing shops have an active registration QR code ###
    import base64
    import os
    import secrets
    import hashlib
    from datetime import datetime, timezone
    import uuid
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    from app.core.config import settings

    key_bytes = base64.b64decode(settings.QR_ENCRYPTION_KEY)
    aesgcm = AESGCM(key_bytes)

    bind = op.get_bind()
    shops = bind.execute(sa.text("SELECT id, owner_user_id FROM shops")).fetchall()
    now = datetime.now(timezone.utc)

    for shop_row in shops:
        shop_id = shop_row[0]
        owner_id = shop_row[1]
        raw_token = secrets.token_urlsafe(32)
        token_hash = hashlib.sha256(raw_token.encode("utf-8")).hexdigest()
        nonce = os.urandom(12)
        ciphertext = aesgcm.encrypt(nonce, raw_token.encode("utf-8"), None)
        encrypted_token = base64.b64encode(nonce + ciphertext).decode("utf-8")
        token_id = uuid.uuid4()

        bind.execute(
            sa.text(
                "INSERT INTO shop_registration_tokens (id, shop_id, token_hash, encrypted_token, is_active, created_at, updated_at) "
                "VALUES (:id, :shop_id, :token_hash, :encrypted_token, true, :now, :now)"
            ),
            {
                "id": token_id,
                "shop_id": shop_id,
                "token_hash": token_hash,
                "encrypted_token": encrypted_token,
                "now": now,
            }
        )

        bind.execute(
            sa.text(
                "INSERT INTO shop_qr_audit_logs (id, shop_id, token_id, action, performed_by_user_id, created_at) "
                "VALUES (:id, :shop_id, :token_id, 'GENERATED', :owner_id, :now)"
            ),
            {
                "id": uuid.uuid4(),
                "shop_id": shop_id,
                "token_id": token_id,
                "owner_id": owner_id,
                "now": now,
            }
        )
    # ### end Alembic commands ###


